const nodes = selector => document.querySelectorAll(selector);
const byId = id => document.getElementById(id);
const lessons = [
  { id: 'frame-setup', progress: 'framePractised', button: 'frame-done', status: 'frame-status' },
  { id: 'chain-stitch', progress: 'practised', button: 'done', status: 'progress-status' },
  { id: 'curves-corners', progress: 'curvesPractised', button: 'curves-done', status: 'curves-status' },
  { id: 'adding-beads', progress: 'beadsPractised', button: 'beads-done', status: 'beads-status' },
  { id: 'floral-motif', progress: 'flowerPractised', button: 'flower-done', status: 'flower-status' },
  { id: 'backstitch', progress: 'backstitchPractised', button: 'backstitch-done', status: 'backstitch-status' },
  { id: 'spiral-chain', progress: 'spiralPractised', button: 'spiral-done', status: 'spiral-status' },
  { id: 'long-short-chain', progress: 'longShortPractised', button: 'long-short-done', status: 'long-short-status' },
];
const key = 'aari-studio-practice';
const state = { language: 'en', framePractised: false, practised: false, curvesPractised: false, beadsPractised: false, flowerPractised: false, backstitchPractised: false, spiralPractised: false, longShortPractised: false, saved: false, readyChoice: null };
let storageError = false;
try {
  const stored = JSON.parse(localStorage.getItem(key));
  if (stored && typeof stored === 'object') {
    state.language = stored.language === 'ta' ? 'ta' : 'en';
    for (const { progress } of lessons) state[progress] = stored[progress] === true;
    state.saved = stored.saved === true;
    state.readyChoice = typeof stored.readyChoice === 'string' ? stored.readyChoice : null;
  }
} catch {
  storageError = true;
}

function fillList(id, items) {
  byId(id).replaceChildren(...items.map(text => {
    const li = document.createElement('li');
    li.textContent = text;
    return li;
  }));
}

function renderContent() {
  const t = copy[state.language];
  document.documentElement.lang = state.language;
  nodes('.stitch-demo video').forEach(video => {
    for (const track of video.textTracks) track.mode = track.language === state.language ? 'showing' : 'disabled';
  });
  byId('language').textContent = state.language === 'en' ? 'தமிழ்' : 'English';
  byId('language').lang = state.language === 'en' ? 'ta' : 'en';
  nodes('[data-i]').forEach(node => { node.textContent = t[node.dataset.i]; });
  nodes('[data-alt]').forEach(node => { node.alt = t[node.dataset.alt]; });
  nodes('[data-label]').forEach(node => node.setAttribute('aria-label', t[node.dataset.label]));
  fillList('frame-tools', t.frameTools);
  fillList('frame-steps', t.frameSteps);
  fillList('tools', t.toolsList);
  fillList('steps', t.steps);
  fillList('curves-tools', t.curvesTools);
  fillList('curves-steps', t.curvesSteps);
  fillList('beads-tools', t.beadsTools);
  fillList('beads-steps', t.beadsSteps);
  fillList('flower-tools', t.flowerTools);
  fillList('flower-steps', t.flowerSteps);
  fillList('backstitch-tools', t.backstitchTools);
  fillList('backstitch-steps', t.backstitchSteps);
  fillList('spiral-tools', t.spiralTools);
  fillList('spiral-steps', t.spiralSteps);
  fillList('long-short-tools', t.longShortTools);
  fillList('long-short-steps', t.longShortSteps);
}

function renderStatus() {
  const t = copy[state.language];
  const start = byId('start');
  const next = lessons.find(lesson => !state[lesson.progress]);
  start.href = next ? '#' + next.id : '#learn';
  start.textContent = next === lessons[0] && !lessons.some(lesson => state[lesson.progress])
    ? t.start : next ? t.resume : t.review;
  for (const { progress, button, status } of lessons) {
    const complete = state[progress];
    byId(button).textContent = complete ? t.undo : t.done;
    byId(button).setAttribute('aria-pressed', complete);
    byId(status).textContent = complete ? t.complete : t.incomplete;
  }
  byId('save').textContent = state.saved ? t.saved : t.save;
  byId('save').setAttribute('aria-pressed', state.saved);
  byId('saved-status').textContent = state.saved ? t.saved : t.unsaved;
  byId('notice').textContent = storageError ? t.storageIssue : '';
}

function persist() {
  try {
    localStorage.setItem(key, JSON.stringify(state));
    storageError = false;
  } catch {
    storageError = true;
  }
  renderStatus();
}

byId('language').addEventListener('click', () => {
  state.language = state.language === 'en' ? 'ta' : 'en';
  renderContent();
  persist();
});
for (const { progress, button } of lessons) {
  byId(button).addEventListener('click', () => {
    state[progress] = !state[progress];
    persist();
  });
}
byId('save').addEventListener('click', () => {
  state.saved = !state.saved;
  persist();
});
function showLesson(id) {
  nodes('.lesson-panel').forEach(panel => {
    panel.hidden = panel.id !== id;
    if (panel.hidden) panel.querySelector('video')?.pause();
  });
  nodes('.lesson-nav a').forEach(link => {
    if (link.hash === '#' + id) link.setAttribute('aria-current', 'location');
    else link.removeAttribute('aria-current');
  });
}

const lessonIds = lessons.map(lesson => lesson.id);
const lessonFromHash = () => location.hash.slice(1);
window.addEventListener('hashchange', () => {
  const id = lessonFromHash();
  if (lessonIds.includes(id)) {
    showLesson(id);
    byId(id).scrollIntoView();
  }
});

document.addEventListener('click', event => {
  if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  const id = event.target.closest('a')?.hash.slice(1);
  if (lessonIds.includes(id)) showLesson(id);
});

renderContent();
renderStatus();
showLesson(lessonIds.includes(lessonFromHash()) ? lessonFromHash() : 'frame-setup');
